-- ============================================================================
-- 0047_listing_favorite.sql · 商品收藏（最小闭环）· public.listing_favorite 全量 DDL
--   1 表 + 2 FK + 1 表级 UNIQUE + 1 PK + 1 读路径索引
-- ============================================================================
-- 内容契约（服务面 = 本批三收藏口：GET /api/favorites · POST /api/favorites ·
--   DELETE /api/favorites/:listingId；行文风格沿 0045_message_conversation.sql /
--   0046_telegram_binding.sql 现文）：
--   · fav_id  bigint GENERATED BY DEFAULT AS IDENTITY —— 主键（「大 serial」口径，
--     与同族 0015 `listing` / `listing_order` 的 identity 体例一致）。
--   · fav_uid bigint NOT NULL —— 收藏者；FK public.users(uid)（DL78：uid 列一律 FK users）。
--   · listing_id bigint NOT NULL —— 被藏商品；FK public.listing(listing_id)
--     （0045 conversation.listing_fk 同法）。
--   · time_created timestamptz NOT NULL DEFAULT now()（R5：不接受客户端传时间）。
--   · 幂等承重墙 = 表级 UNIQUE(fav_uid, listing_id)：重复收藏撞唯一 ⇒ 服务层
--     ON CONFLICT DO NOTHING 取既有行回现态（0045 conversation UNIQUE(listing_id, buyer_uid)
--     的「自然键 + 取既有行」同法）；不落第二行。
--   · 取消收藏 = 物理 DELETE（收藏关系非法律往来留痕，不入 0045 式禁删触发器族）；
--     重复 DELETE = 0 行 ⇒ 服务层仍回成功（幂等删除）。
--   · 无资金动作：不写 ledger、不借账本错误码、不新增 kind（收藏不入账）。
--   · 无状态机 / 无软删列 / 无内容列：行 = 纯关系（1 用户 × 1 商品 = 至多 1 行）。
--
-- 硬禁（同 0045/0046）：不改任何既有对象 / 不 CREATE OR REPLACE 既有函数体 /
--   不写业务数据；0001–0046 一字不动（checksum 冻结，migrate.ts 整链 ABORT 红线沿用）。
-- 幂等（DL48 体例）：CREATE TABLE IF NOT EXISTS + CREATE INDEX IF NOT EXISTS +
--   末尾 apply-time DO 自检（纯目录只读）；任一失败 ⇒ 整迁移回滚、不写版本行。
-- ============================================================================


-- ============================================================================
-- §① 表 public.listing_favorite
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.listing_favorite (
  fav_id       bigint      GENERATED BY DEFAULT AS IDENTITY,
  fav_uid      bigint      NOT NULL,
  listing_id   bigint      NOT NULL,
  time_created timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT listing_favorite_pk         PRIMARY KEY (fav_id),
  -- 幂等承重墙：1 收藏者 × 1 商品 = 至多 1 行（重复收藏不落第二行）
  CONSTRAINT listing_favorite_fav_uniq   UNIQUE (fav_uid, listing_id),
  CONSTRAINT listing_favorite_uid_fk     FOREIGN KEY (fav_uid)    REFERENCES public.users(uid),
  CONSTRAINT listing_favorite_listing_fk FOREIGN KEY (listing_id) REFERENCES public.listing(listing_id)
);

COMMENT ON TABLE public.listing_favorite IS
  '商品收藏关系表（最小闭环）：per (fav_uid, listing_id) 至多 1 行；取消 = 物理 DELETE（幂等，删 0 行亦成功）；无资金动作 ⇒ 不入账本、不借账本错误码。';

-- 「我的收藏」读路径（fav_uid 前导 + 收藏时间降序；同刻并列以 fav_id DESC 稳定排序）。
-- (fav_uid, listing_id) 判重 / 删除走 UNIQUE 约束自带索引，不另建。
CREATE INDEX IF NOT EXISTS idx_listing_favorite_fav
  ON public.listing_favorite (fav_uid, time_created DESC, fav_id DESC);


-- ============================================================================
-- §② apply-time 自检（纯目录只读 · 不 INSERT / 不 UPDATE / 不借账本错误码）
--     逐项断言「DDL 全在场」；任一缺席 ⇒ RAISE ⇒ 整迁移回滚、不写版本行。
-- ============================================================================

DO $$
DECLARE
  missing  text;
  fk_count int;
BEGIN
  -- ②-a 表在场
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'listing_favorite'
      AND table_type = 'BASE TABLE'
  ) THEN
    RAISE EXCEPTION 'apply self-check failed: missing table listing_favorite';
  END IF;

  -- ②-b 4 列逐名在场
  SELECT string_agg(v.col, ',') INTO missing FROM (
    VALUES ('fav_id'), ('fav_uid'), ('listing_id'), ('time_created')
  ) AS v(col)
  WHERE NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'listing_favorite'
      AND column_name = v.col
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'apply self-check failed: missing column(s): %', missing;
  END IF;

  -- ②-c 1 PK + 1 UNIQUE + 2 FK 逐名在场
  SELECT string_agg(v.conname, ',') INTO missing FROM (
    VALUES ('listing_favorite_pk'), ('listing_favorite_fav_uniq'),
           ('listing_favorite_uid_fk'), ('listing_favorite_listing_fk')
  ) AS v(conname)
  WHERE NOT EXISTS (
    SELECT 1 FROM pg_constraint con
    JOIN pg_class cls ON cls.oid = con.conrelid
    JOIN pg_namespace nsp ON nsp.oid = cls.relnamespace
    WHERE nsp.nspname = 'public' AND con.conname = v.conname
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'apply self-check failed: missing constraint(s): %', missing;
  END IF;

  -- ②-d FK 指向核对（users / listing 两目标）
  SELECT count(*)::int INTO fk_count FROM pg_constraint con
   WHERE con.conname IN ('listing_favorite_uid_fk', 'listing_favorite_listing_fk')
     AND con.contype = 'f'
     AND con.confrelid IN ('public.users'::regclass, 'public.listing'::regclass);
  IF fk_count <> 2 THEN
    RAISE EXCEPTION 'apply self-check failed: listing_favorite FK targets wrong (found %/2)', fk_count;
  END IF;

  -- ②-e 读路径索引在场
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public' AND indexname = 'idx_listing_favorite_fav'
  ) THEN
    RAISE EXCEPTION 'apply self-check failed: index idx_listing_favorite_fav missing';
  END IF;

  RAISE NOTICE '0047 self-check OK: listing_favorite cols=4 / 1 pk + 1 uniq + 2 fk / 1 index';
END $$;
